# Attempt to extract the location from the provided context
import re

ctx = context
location = None

# Look for a direct sentence mentioning "Stevens Institute of Technology" and a location
pattern = r"Stevens Institute of Technology.*?(located|located in|is located in)\s+([A-Za-z\s\-]+)\."
for line in ctx.splitlines():
    if "Stevens Institute of Technology" in line:
        m = re.search(pattern, line)
        if m:
            location = m.group(2).strip().rstrip(".")
            break

if location:
    print("Detected location:", location)
else:
    # Fallback checks
    if "Mumbai" in ctx:
        location = "Mumbai"
        print("Detected location (fallback):", location)
    elif "Hoboken" in ctx:
        location = "Hoboken, New Jersey"
        print("Detected location (fallback):", location)
    else:
        print("Location could not be determined from the current context.")
